const SAVE_KEY = 'viva-save-v2';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const clamp = (value, min = 0, max = 100) => Math.max(min, Math.min(max, value));
const money = value => `R$ ${Math.round(value).toLocaleString('pt-BR')}`;
const pick = list => list[Math.floor(Math.random() * list.length)];

const initialState = () => ({
  version: 2, name: 'Alex Martins', pronouns: 'ele/dele', country: 'Brasil', city: 'São Paulo',
  age: 24, year: 2025, money: 8420, happiness: 88, health: 92, reputation: 64,
  stress: 18, karma: 50, fame: 12, energy: 78, education: 76,
  talent: 'criatividade', trait: 'ambicioso', avatar: 'AM', dead: false,
  career: { title: 'Designer de Produto', company: 'Estúdio Aurora', salary: 7800, level: 4, skill: 78, employed: true },
  finances: { investments: 42000, property: 480000, vehicle: 126000, expenses: 3240, debt: 0 },
  skills: { criatividade: 78, inteligência: 70, carisma: 64, atletismo: 55, liderança: 62 },
  relationships: [
    { id: 'marina', name: 'Marina Costa', role: 'Melhor amiga', initials: 'MC', color: '#d79487', affinity: 86, type: 'friend', romance: 12 },
    { id: 'rafa', name: 'Rafa Mendes', role: 'Parceiro de aventuras', initials: 'RM', color: '#749a94', affinity: 72, type: 'friend', romance: 18 },
    { id: 'joao', name: 'João Martins', role: 'Irmão', initials: 'JM', color: '#7899b2', affinity: 94, type: 'family', romance: 0 },
    { id: 'lia', name: 'Lia Nakamura', role: 'Colega de trabalho', initials: 'LN', color: '#aa8fba', affinity: 48, type: 'colleague', romance: 8 }
  ],
  events: [
    { icon: '✦', cls: '', title: 'Uma ideia tomou forma', text: 'Você teve uma visão para um projeto pessoal. Talvez seja hora de tirar do papel.', time: 'Hoje, 09:42' },
    { icon: '♧', cls: 'blue', title: 'Marina curtiu sua foto', text: '“Aquele fim de semana foi inesquecível! Precisamos repetir.”', time: 'Ontem, 20:18' },
    { icon: '↗', cls: 'pink', title: 'Você recebeu uma promoção', text: 'Seu trabalho no Estúdio Aurora foi reconhecido. Parabéns, designer!', time: 'Há 3 dias' }
  ]
});

let state = loadState();
function loadState() {
  try { const saved = JSON.parse(localStorage.getItem(SAVE_KEY)); return saved ? { ...initialState(), ...saved } : initialState(); }
  catch { return initialState(); }
}
function saveState() { localStorage.setItem(SAVE_KEY, JSON.stringify(state)); const dot = $('.save-state .dot'); if (dot) dot.style.background = '#7dbe63'; }
function toast(message) { const el = $('#toast'); if (!el) return; el.textContent = message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2600); }
function addEvent(icon, title, text, cls = '') { state.events.unshift({ icon, title, text, cls, time: 'Agora' }); state.events = state.events.slice(0, 7); renderEvents(); saveState(); }
function renderEvents() { const list = $('#eventList'); if (list) list.innerHTML = state.events.map(e => `<div class="event"><div class="event-icon ${e.cls || ''}">${e.icon}</div><div><b>${e.title}</b><p>${e.text}</p><time>${e.time}</time></div></div>`).join(''); }
function setStat(name, value) { state[name] = clamp(value); }
function changeStat(name, amount) { setStat(name, (state[name] || 0) + amount); render(); }
function requireFunds(amount) { if (state.money < amount) { toast(`Você precisa de ${money(amount - state.money)} a mais.`); return false; } state.money -= amount; return true; }
function openModal(title, text, action, confirm = 'Escolher este caminho') { $('#modalTitle').textContent = title; $('#modalText').textContent = text; $('#modalOk').textContent = confirm; $('#modal').classList.remove('hidden'); $('#modalOk').onclick = () => { $('#modal').classList.add('hidden'); if (action) action(); }; }
function closeModal() { $('#modal')?.classList.add('hidden'); }

function render() {
  const setText = (selector, text) => { const el = $(selector); if (el) el.textContent = text; };
  setText('#sideName', state.name); setText('#sideAge', `${state.age} anos · ${state.city}, ${state.country}`); setText('#money', money(state.money));
  const stat = (id, value) => { const el = $(`#${id}`); if (el) el.innerHTML = `${Math.round(value)}<span class="unit">/100</span>`; };
  stat('happiness', state.happiness); stat('reputation', state.reputation);
  const healthCard = $('.stats-grid .stat-card:nth-child(2) strong'); if (healthCard) healthCard.innerHTML = `${Math.round(state.health)}<span class="unit">/100</span>`;
  const bars = $('.stats-grid .stat-card:nth-child(2) .progress i'); if (bars) bars.style.width = `${state.health}%`;
  const mood = state.happiness > 80 ? 'se sentindo inspirado' : state.happiness > 55 ? 'em equilíbrio' : state.happiness > 30 ? 'um pouco abatido' : 'precisando de cuidado';
  setText('#moodText', mood); const moodPercent = $('.mood i'); if (moodPercent) moodPercent.textContent = `${Math.round(state.happiness)}%`;
  const avatar = $('.avatar'); if (avatar) avatar.textContent = state.avatar || state.name.slice(0, 2).toUpperCase(); const mini = $('.avatar-mini'); if (mini) mini.textContent = (state.avatar || state.name.slice(0, 2)).slice(0, 2);
  setText('#relCount', state.relationships.length); setText('#netWorth', money(state.money + state.finances.investments + state.finances.property + state.finances.vehicle - state.finances.debt));
  renderEvents(); renderPeople(); renderCareer(); renderHealth(); saveState();
}
function renderCareer() {
  const c = state.career; const hero = $('.career-hero'); if (!hero) return;
  const tag = $('.career-hero .tag'); if (tag) tag.textContent = c.employed ? `EM ASCENSÃO · NÍVEL ${c.level}` : 'EM BUSCA DE UMA OPORTUNIDADE';
  const title = $('.career-hero h2'); if (title) title.textContent = c.title;
  const place = $('.career-hero p'); if (place) place.textContent = `${c.company} · ${state.city}, ${state.country}`;
  const salary = $('.career-salary strong'); if (salary) salary.textContent = money(c.salary);
  const skills = $('#skills'); if (skills) skills.innerHTML = Object.entries(state.skills).map(([name, value]) => `<div class="skill"><div class="skill-top"><b>${name[0].toUpperCase() + name.slice(1)}</b><span>${Math.round(value)}/100</span></div><div class="skill-bar"><i style="width:${value}%"></i></div></div>`).join('');
}
function renderPeople() {
  const grid = $('#peopleGrid'); if (!grid) return;
  grid.innerHTML = state.relationships.map(person => `<div class="person"><div class="person-avatar" style="background:${person.color}">${person.initials}</div><div><h3>${person.name}</h3><p>${person.role}${person.romance > 40 ? ' · interesse romântico' : ''}</p><div class="relationship"><i style="width:${person.affinity}%"></i></div></div><button data-rel="${person.id}">Interagir</button></div>`).join('');
  $$('[data-rel]', grid).forEach(button => button.onclick = () => relationshipMenu(state.relationships.find(p => p.id === button.dataset.rel)));
}
function renderHealth() {
  const ring = $('.health-ring'); if (ring) ring.innerHTML = `${Math.round(state.health)}<span>/100</span>`;
  const bars = $$('#saudeView .skill-bar i'); if (bars.length >= 3) { bars[0].style.width = `${state.health}%`; bars[1].style.width = `${clamp(state.happiness - state.stress / 2)}%`; bars[2].style.width = `${state.stress}%`; }
}
function relationshipMenu(person) {
  if (!person) return;
  openModal(`Interagir com ${person.name}`, `A afinidade atual é ${person.affinity}/100. Uma ação cuidadosa pode aproximar vocês — ou criar uma história inesperada.`, () => {
    const gain = state.trait === 'gentil' ? 8 : 5; person.affinity = clamp(person.affinity + gain); person.romance = clamp(person.romance + (person.type === 'friend' ? 2 : 0)); setStat('happiness', state.happiness + 2); addEvent('♡', `Você esteve com ${person.name}`, 'Uma conversa sincera fortaleceu esse vínculo.', 'pink'); render();
  }, 'Conversar');
}

function advanceYear() {
  if (state.dead) return toast('Esta vida chegou ao fim. Comece uma nova história.');
  state.age++; state.year++; const c = state.career;
  const income = c.employed ? c.salary * 12 : 0; const expenses = state.finances.expenses * 12;
  state.money += income - expenses; const returnRate = (Math.random() * .12) - .02; state.finances.investments = Math.max(0, state.finances.investments * (1 + returnRate));
  state.health -= state.age > 65 ? 3 : state.stress > 65 ? 2 : 0.5; state.happiness -= state.money < 0 ? 6 : 1; state.stress = clamp(state.stress + 4 - (state.trait === 'espiritual' ? 2 : 0));
  state.relationships.forEach(p => { p.affinity = clamp(p.affinity - (Math.random() < .35 ? 2 : 0)); });
  if (c.employed && Math.random() < .35) { c.skill = clamp(c.skill + 3); c.level = Math.min(10, c.level + (c.skill > c.level * 20 ? 1 : 0)); c.salary = Math.round(c.salary * 1.05); }
  const event = yearlyEvent(); addEvent(event.icon, event.title, event.text, event.cls); saveState(); render(); toast(`Ano ${state.year}: ${income >= expenses ? 'suas contas fecharam no azul' : 'suas despesas superaram a renda'}`);
  if (state.health <= 0 || state.age >= 105) { state.dead = true; addEvent('☾', 'O fim de uma jornada', 'Sua história terminou, mas seu legado permanece.', 'pink'); }
}
function yearlyEvent() {
  const events = [
    { icon: '✦', title: 'Um novo capítulo', text: 'Você percebeu que pequenas escolhas mudaram completamente seu caminho.' },
    { icon: '♧', title: 'Um hábito saudável', text: 'Sua rotina melhorou e você encontrou mais equilíbrio.', cls: 'blue' },
    { icon: '↗', title: 'Reconhecimento profissional', text: 'Seu trabalho chamou atenção e uma oportunidade apareceu.', cls: 'pink' },
    { icon: '♡', title: 'Uma mensagem inesperada', text: `${pick(state.relationships).name} lembrou de você e propôs um encontro.`, cls: 'pink' }
  ]; return pick(events);
}
function quickAction(type) {
  const actions = {
    explore: ['Uma descoberta inesperada', 'Você encontrou uma livraria escondida. Um livro raro custou R$ 45.', () => { if (!requireFunds(45)) return; changeStat('happiness', 4); addEvent('⌁', 'Uma nova descoberta', 'Uma livraria escondida mudou seu caminho hoje.'); }],
    learn: ['Hora de crescer', 'Um curso intensivo vai consumir tempo, mas aumentar sua habilidade.', () => { state.education = clamp(state.education + 5); state.skills[state.talent] = clamp((state.skills[state.talent] || 50) + 4); changeStat('happiness', 2); addEvent('⊙', 'Você começou a aprender', 'Um curso abriu novas possibilidades.', 'blue'); }],
    social: ['Um convite especial', 'Marina está organizando um jantar. O custo é R$ 80, mas a conexão pode valer muito mais.', () => { if (!requireFunds(80)) return; const p = state.relationships[0]; p.affinity = clamp(p.affinity + 8); changeStat('happiness', 5); changeStat('reputation', 2); addEvent('♧', 'Uma noite memorável', `Você passou a noite com ${p.name}.`, 'pink'); }],
    rest: ['Pausa merecida', 'Você desligou o celular e recuperou as energias.', () => { state.stress = clamp(state.stress - 12); state.energy = clamp(state.energy + 15); changeStat('happiness', 3); addEvent('☾', 'Você cuidou de si', 'Descanso também é parte da jornada.'); }]
  }; const action = actions[type]; if (action) openModal(action[0], action[1], action[2]);
}
function activity(type) {
  const actions = {
    gym: ['Academia', 'Uma sessão custa R$ 40 e melhora seu condicionamento.', () => { if (!requireFunds(40)) return; state.health = clamp(state.health + 5); state.stress = clamp(state.stress - 2); state.skills.atletismo = clamp(state.skills.atletismo + 2); addEvent('♧', 'Treino concluído', 'Você venceu a preguiça hoje.'); }],
    music: ['Música', 'Você publicou uma música e pode começar uma carreira artística.', () => { state.skills.criatividade = clamp(state.skills.criatividade + 3); changeStat('reputation', 3); addEvent('♫', 'Sua música ganhou atenção', 'Um pequeno começo pode virar uma grande carreira.', 'blue'); }],
    volunteer: ['Voluntariado', 'Você passou a tarde ajudando uma ONG local.', () => { state.karma = clamp(state.karma + 4); changeStat('reputation', 6); changeStat('happiness', 3); addEvent('♡', 'Você fez a diferença', 'Seu tempo ajudou quem precisava.', 'pink'); }],
    casino: ['Cassino', 'Você pode apostar R$ 200. A chance de ganhar é pequena, e perder também dói.', () => { if (!requireFunds(200)) return; if (Math.random() < .38) { state.money += 600; addEvent('♢', 'Uma aposta deu certo', 'Você saiu antes de perder o controle.'); } else { state.stress = clamp(state.stress + 8); addEvent('♢', 'A sorte não veio', 'Você perdeu a aposta e decidiu aprender com o limite.'); } }],
    dating: ['Encontro', 'Um encontro casual pode virar uma relação nova.', () => { const p = { id: `new-${Date.now()}`, name: pick(['Bea Lima', 'Caio Torres', 'Nina Alves', 'Theo Reis']), role: 'Novo interesse', initials: '♡', color: '#c88d9b', affinity: 55, romance: 45, type: 'romance' }; state.relationships.push(p); changeStat('happiness', 5); addEvent('♥', 'Um encontro promissor', `${p.name} entrou na sua história.`, 'pink'); }],
    meditate: ['Meditação', 'Você respirou fundo e deixou o celular de lado.', () => { state.stress = clamp(state.stress - 10); changeStat('happiness', 4); addEvent('☾', 'Momento de paz', 'Você encontrou silêncio em meio ao caos.'); }],
    crime: ['Vida do crime', 'Um contato ofereceu um trabalho ilegal. O risco de investigação é real.', () => { if (Math.random() < .55) { state.money += 5000; state.karma = clamp(state.karma - 10); changeStat('reputation', -15); addEvent('⚠', 'Uma escolha perigosa', 'Dinheiro fácil trouxe consequências para sua reputação.'); } else { state.money -= 1000; state.stress = clamp(state.stress + 20); addEvent('⚠', 'O plano deu errado', 'Você escapou, mas perdeu dinheiro e tranquilidade.'); } }],
    fame: ['Buscar fama', 'Um vídeo seu pode viralizar, mas a exposição cobra seu preço.', () => { changeStat('reputation', 10); state.fame += 8; state.stress = clamp(state.stress + 3); addEvent('★', 'Você ficou famoso', 'Seu rosto está em todos os lugares hoje.', 'blue'); }]
  }; const action = actions[type]; if (action) openModal(action[0], action[1], action[2]);
}
function setupBindings() {
  $$('.nav-item').forEach(button => button.onclick = () => { $$('.nav-item').forEach(b => b.classList.remove('active')); button.classList.add('active'); $$('.section-view').forEach(view => view.classList.add('hidden')); $(`#${button.dataset.section}View`)?.classList.remove('hidden'); });
  $$('.action-grid button').forEach(button => button.onclick = () => quickAction(button.dataset.action));
  $$('.activity-grid button').forEach(button => button.onclick = () => activity(button.dataset.game));
  $('#ageBtn').onclick = () => openModal('Virar um ano', 'O tempo passa, suas contas são processadas e as relações mudam. Quer descobrir o próximo capítulo?', advanceYear, 'Avançar');
  $('#jobBtn').onclick = () => openModal('Uma proposta chegou', 'Uma startup quer você como líder de design. O salário será maior, mas o risco também.', () => { state.career.title = 'Líder de Design'; state.career.company = 'Núcleo Lab'; state.career.salary += 2400; state.career.level++; addEvent('↗', 'Você aceitou uma proposta', 'Uma mudança profissional abriu novas possibilidades.', 'blue'); render(); });
  $('#meetBtn').onclick = () => activity('dating'); $('#newQuote').onclick = () => { const q = pick([['O futuro pertence a quem acredita na beleza de seus sonhos.', '— Eleanor Roosevelt'], ['Não conte os dias, faça os dias contarem.', '— Muhammad Ali'], ['Tudo parece impossível até que seja feito.', '— Nelson Mandela']]); $('#quote').textContent = q[0]; $('#quote').nextElementSibling.textContent = q[1]; toast('Nova reflexão encontrada'); };
  $('#settingsBtn').onclick = () => toast('Seu progresso está salvo neste dispositivo.'); $('#closeModal').onclick = $('#modalCancel').onclick = closeModal;
  $$('[data-modal]').forEach(button => button.onclick = () => modalAction(button.dataset.modal));
  $('#newLife').onclick = () => $('#customizer').classList.remove('hidden'); $('#closeCreator').onclick = () => $('#customizer').classList.add('hidden');
  $$('.appearance-options button').forEach(button => button.onclick = () => { $$('.appearance-options button').forEach(b => b.classList.remove('selected')); button.classList.add('selected'); });
  $('#createLife').onclick = createLife;
}
function modalAction(type) {
  const actions = {
    study: ['Matricular-se em um curso', 'Uma formação pode transformar seu futuro. O primeiro passo exige disciplina.', () => { state.education = clamp(state.education + 8); state.skills.inteligência = clamp(state.skills.inteligência + 4); addEvent('⌘', 'Você voltou a estudar', 'Uma nova habilidade foi adicionada ao seu repertório.'); }],
    invest: ['Investir dinheiro', 'Aplique R$ 500 em uma carteira diversificada. O retorno nunca é garantido.', () => { if (!requireFunds(500)) return; state.finances.investments += 500; addEvent('▣', 'Você fez um investimento', 'Sua carteira ganhou uma nova posição.'); }],
