220: function advanceYear() {
221:   if (state.dead) return toast('Esta vida chegou ao fim. Comece uma nova história.');
222:   state.age++; state.year++; const c = state.career;
223:   const wasInPrison = state.prisonYears > 0;
224:   if (wasInPrison) state.prisonYears = Math.max(0, state.prisonYears - 1);
225:   const income = c.employed && state.prisonYears === 0 && !wasInPrison ? c.salary * 12 : 0;
226:   const expenses = Math.round(state.finances.expenses * 12 * (1 + state.age / 500));
227:   const investmentReturn = state.finances.investments * ((Math.random() * .12) - .03);
228:   state.finances.investments = Math.max(0, state.finances.investments + investmentReturn);
229:   const balanceBeforeDebt = state.money + income - expenses;
230:   const deficit = Math.max(0, -balanceBeforeDebt);
231:   state.money = Math.max(0, balanceBeforeDebt);
232:   if (deficit) { state.finances.debt += deficit; state.credit = clamp(state.credit - 35, 0, 900); }
233:   else { state.finances.debt = Math.max(0, state.finances.debt - Math.min(state.finances.debt, income * .05)); state.credit = clamp(state.credit + 8, 0, 900); }
234:   const agePenalty = state.age > 70 ? 2.5 : state.age > 45 ? 1 : .25;
235:   state.health -= agePenalty + (state.stress > 70 ? 1.5 : 0);
236:   state.happiness += deficit ? -6 : state.money > expenses ? 1 : -1;
237:   state.stress = clamp(state.stress + 3 + (deficit ? 5 : 0) - (state.trait === 'espiritual' ? 2 : 0));
238:   state.energy = clamp(state.energy + (state.age < 30 ? 2 : -3));
239:   state.relationships.forEach(person => { person.affinity = clamp(person.affinity - (Math.random() < .4 ? 2 : 0)); });
240:   state.children.forEach(child => { child.age = safeNumber(child.age) + 1; });
241:   if (c.employed) {
242:     c.skill = clamp(c.skill + (state.education > 70 ? 4 : 2));
243:     if (Math.random() < .3 && c.level < 10) { c.level++; c.salary = Math.round(c.salary * 1.08); addEvent('↗', 'Uma promoção chegou', `Seu salário agora é ${money(c.salary)} por mês.`, 'blue'); }
244:   }
245:   if (state.age >= 45 && Math.random() < .08 && !state.healthConditions.includes('pressão alta')) state.healthConditions.push('pressão alta');
246:   const event = yearlyEvent(); addEvent(event.icon, event.title, event.text, event.cls);
247:   if (wasInPrison) addEvent('⚖', 'Um ano difícil', state.prisonYears ? `Você cumpriu mais um ano de prisão. Restam ${state.prisonYears}.` : 'Você cumpriu sua pena e está tentando reconstruir a vida.', 'pink');
248:   state.history.push({ year: state.year, age: state.age, money: Math.round(state.money), career: c.title });
249:   if (state.health <= 0 || (state.age >= 92 && Math.random() < .15) || state.age >= 105) {
250:     state.dead = true; addEvent('☾', 'O fim de uma jornada', 'Sua história terminou, mas seu legado permanece.', 'pink');
251:   }
252:   commit(`Ano ${state.year}: ${income >= expenses ? 'suas contas fecharam no azul' : 'suas despesas exigiram atenção'}`);
253: }
